#!/usr/bin/env bash
# Build a demo channel line-up for screenshots and demos: made-up channel
# names, video generated by FFmpeg (no copyrighted content), a guide timed
# around "now". Output: build/demo/ (git-ignored).
#
#   tests/demo/make-demo.sh            # needs ffmpeg (with libx264) and python3
#
# The playlist uses relative paths, so the folder can be copied anywhere
# (scripts/demo-shots.sh copies it to the Pi).
set -euo pipefail
cd "$(dirname "$0")/../.."
OUT=build/demo
SECS=${SECS:-120}
mkdir -p "$OUT"

# number|name|group|tvg-id|ffmpeg video source|size|fps|tone Hz
CHANNELS=(
  "2|Fractal Movies|Movies|fractal.demo|mandelbrot=size=640x480:rate=25:maxiter=200|640x480|25|330"
  "5|Life Science|Documentary|life.demo|life=size=640x480:rate=30:mold=10:ratio=0.08:life_color=#ffcf40:death_color=#18185a|640x480|30|440"
  "7|Gradient Kids|Kids|gradient.demo|gradients=size=1280x720:rate=30:speed=0.02:n=4|1280x720|30|523"
  "9|Pattern News|News|pattern.demo|testsrc2=size=1280x720:rate=30|1280x720|30|660"
  "11|Rule 110 Music|Music|rule110.demo|cellauto=size=640x480:rate=30:rule=110:scroll=1|640x480|30|392"
)

for c in "${CHANNELS[@]}"; do
  IFS='|' read -r num name group id src size fps hz <<<"$c"
  f="$OUT/ch$num.ts"
  [[ -f $f ]] && continue
  echo "making $f ($name)"
  ffmpeg -nostdin -hide_banner -loglevel error -y \
    -f lavfi -i "$src" -f lavfi -i "sine=frequency=$hz:sample_rate=48000" -t "$SECS" \
    -vf "scale=$size,format=yuv420p" -r "$fps" -c:v libx264 -preset veryfast -crf 26 -g "$fps" \
    -af "volume=-12dB" -c:a aac -b:a 96k -ac 2 -f mpegts "$f"
done

{
  echo '#EXTM3U x-tvg-url="guide.xml"'
  for c in "${CHANNELS[@]}"; do
    IFS='|' read -r num name group id _ _ _ _ <<<"$c"
    echo "#EXTINF:-1 tvg-id=\"$id\" tvg-chno=\"$num\" group-title=\"$group\",$name"
    echo "ch$num.ts"
  done
  echo '#EXTINF:-1 tvg-id="weather.demo" tvg-chno="98" group-title="Info",Weather Radar'
  echo 'http://10.255.255.1/weather.ts'                 # unreachable: tuning static
  echo '#EXTINF:-1 tvg-id="late.demo" tvg-chno="99" group-title="Movies",Late Night'
  echo 'missing.ts'                                     # no such file: NO SIGNAL
} > "$OUT/demo.m3u"

python3 "$(dirname "$0")/make-guide.py" > "$OUT/guide.xml"
echo "demo ready in $OUT ($(ls "$OUT"/*.ts | wc -l | tr -d ' ') channels)"
